<?php declare(strict_types=1);require_once __DIR__.'/auth.php';$u=portal_require();$q=$db->prepare('SELECT client_id FROM client_portal_users WHERE id=?');$q->execute([$u['id']]);$client=(int)$q->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){$n='TKT-'.date('YmdHis').'-'.random_int(100,999);$q=$db->prepare('INSERT INTO support_tickets(ticket_number,client_id,subject,description,priority,status) VALUES(?,?,?,?,?,"open")');$q->execute([$n,$client,trim($_POST['subject']),trim($_POST['description']),$_POST['priority']]);header('Location: support.php');exit;}$q=$db->prepare('SELECT ticket_number,subject,priority,status,opened_at FROM support_tickets WHERE client_id=? ORDER BY opened_at DESC');$q->execute([$client]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Support</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container py-4"><a href="index.php">← Dashboard</a><h1 class="h3 mt-3">Support</h1><form method="post" class="card card-body mb-4"><input class="form-control mb-2" name="subject" placeholder="Subject" required><textarea class="form-control mb-2" name="description" placeholder="How can we help?" required></textarea><select class="form-select mb-2" name="priority"><option>low</option><option selected>medium</option><option>high</option><option>urgent</option></select><button class="btn btn-dark">Create Ticket</button></form><table class="table"><thead><tr><th>Ticket</th><th>Subject</th><th>Priority</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['ticket_number'])?></td><td><?=htmlspecialchars($r['subject'])?></td><td><?=htmlspecialchars($r['priority'])?></td><td><?=htmlspecialchars($r['status'])?></td></tr><?php endforeach;?></tbody></table></main></body></html>